function validate(input) {
  const [{ SalesPerson = [], Company = [], Orders = [] }] = input;
  const people = new Set(), companies = new Set(), orders = new Set();
  for (const [id] of SalesPerson) {
    if (id === null) return 'Every salesperson needs a sales_id.';
    if (people.has(id)) return `sales_id ${id} appears twice in SalesPerson.`;
    people.add(id);
  }
  for (const [id] of Company) {
    if (id === null) return 'Every company needs a com_id.';
    if (companies.has(id)) return `com_id ${id} appears twice in Company.`;
    companies.add(id);
  }
  for (const [id, , com, seller] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    if (!companies.has(com)) return `Order ${id} names unknown com_id ${com}.`;
    if (!people.has(seller)) return `Order ${id} names unknown sales_id ${seller}.`;
    orders.add(id);
  }
  return null;
}

