function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['John', 'Amy', 'Mark', 'Pam', 'Alex', 'Kim', 'Ravi', 'Sofia'];
  const colors = ['RED', 'ORANGE', 'YELLOW', 'GREEN', 'BLUE', 'REDWOOD'];
  const cities = ['Boston', 'New York', 'Austin'];
  const date = year => `${year}-${String(1 + Math.floor(rand() * 12)).padStart(2, '0')}-${String(1 + Math.floor(rand() * 28)).padStart(2, '0')}`;
  const small = size === 'small';
  const peopleCount = small ? Math.floor(rand() * 7) : 1000;
  const companyCount = small ? Math.floor(rand() * 5) : 120;
  const orderCount = peopleCount && companyCount ? (small ? Math.floor(rand() * 9) : 2000) : 0;
  const SalesPerson = [], Company = [], Orders = [];
  for (let id = 1; id <= peopleCount; id++) SalesPerson.push([id, small ? pick(names) : `${pick(names)} ${id}`, 1000 * (5 + Math.floor(rand() * 95)), 1 + Math.floor(rand() * 25), date(2000 + Math.floor(rand() * 12))]);
  // Company ids are shuffled so that RED does not always sit at com_id 1.
  const ids = Array.from({ length: companyCount }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  for (const id of ids) Company.push([id, pick(colors), pick(cities)]);
  for (let id = 1; id <= orderCount; id++) Orders.push([id, date(2014), pick(ids), 1 + Math.floor(rand() * peopleCount), 1000 * (1 + Math.floor(rand() * 50))]);
  return [{ SalesPerson, Company, Orders }];
}
